        from math import gcd

def _gcd_many(nums):
    g = 0
    for v in nums:
        g = gcd(g, v)
    return abs(g)

def _divisors(n):
    # positive divisors of n
    n = abs(n)
    divs = set()
    i = 1
    while i * i <= n:
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
        i += 1
    return sorted(divs)

def _mod_inv(a, m):
    # modular inverse of a mod m, assumes gcd(a,m)=1
    a %= m
    if m == 1:
        return 0
    # extended Euclid
    r0, r1 = a, m
    s0, s1 = 1, 0
    while r1:
        q = r0 // r1
        r0, r1 = r1, r0 - q * r1
        s0, s1 = s1, s0 - q * s1
    if r0 != 1:
        return None
    return s0 % m

